  blotdyr: '<path d="M3 18h9"/><path d="M12 18a6 6 0 1 0-6-6c0 2.2 1.8 4 4 4s3-1.4 3-3-1.2-2.6-2.5-2.6"/><path d="M18 9c.6-.8 1.4-1.2 2.2-1.2"/>',
