export const ALLERGEN_KEYS = [...Object.keys(OFFICIAL), ...Object.keys(LINE)];

// Ett ikon (uten tekst).
export function allergenIcon(key) {
  const off = OFFICIAL[key];
  if (off) {
    return `<svg class="al-ic al-ic-fill" viewBox="${off.vb}" fill="currentColor" aria-hidden="true">${off.p}</svg>`;
  }
  const line = LINE[key];
  if (line) {
    return `<svg class="al-ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${line}</svg>`;
  }
  return "";
}

// Kompakt rad med bare ikoner (til kort). Navn ligger i title for tilgjengelighet.
export function allergenIcons(keys = []) {
  if (!keys.length) return "";
  return `<ul class="al-row">${keys
    .map(
      (k) =>
        `<li class="al-ic-wrap" title="${esc(ALLERGEN_NAME[k] || k)}">${allergenIcon(k)}</li>`
    )
    .join("")}</ul>`;
}

// Ikon + navn (til detaljvisning).
export function allergenChips(keys = []) {
  if (!keys.length) return "";
  return `<ul class="al-chips">${keys
    .map(
      (k) =>
        `<li class="al-chip">${allergenIcon(k)}<span>${esc(ALLERGEN_NAME[k] || k)}</span></li>`
    )
    .join("")}</ul>`;
}
